package com.nexushr.entity;
import jakarta.persistence.*; import java.time.*; import java.util.UUID; import java.math.BigDecimal;
@Entity @Table(name="payroll") public class Payroll { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) private Employee employee; @Column(nullable=false) private String payrollMonth; @Column(nullable=false,precision=14,scale=2) private BigDecimal basic; @Column(nullable=false,precision=14,scale=2) private BigDecimal allowances=BigDecimal.ZERO; @Column(nullable=false,precision=14,scale=2) private BigDecimal deductions=BigDecimal.ZERO; @Column(nullable=false,precision=14,scale=2) private BigDecimal netPay; @Enumerated(EnumType.STRING) @Column(nullable=false) private PayrollStatus status=PayrollStatus.DRAFT; private LocalDateTime processedAt; public UUID getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public YearMonth getPayrollMonth(){return YearMonth.parse(payrollMonth);} public void setPayrollMonth(YearMonth v){payrollMonth=v.toString();} public BigDecimal getBasic(){return basic;} public void setBasic(BigDecimal v){basic=v;} public BigDecimal getAllowances(){return allowances;} public void setAllowances(BigDecimal v){allowances=v;} public BigDecimal getDeductions(){return deductions;} public void setDeductions(BigDecimal v){deductions=v;} public BigDecimal getNetPay(){return netPay;} public void setNetPay(BigDecimal v){netPay=v;} public PayrollStatus getStatus(){return status;} public void setStatus(PayrollStatus v){status=v;} public LocalDateTime getProcessedAt(){return processedAt;} public void setProcessedAt(LocalDateTime v){processedAt=v;} }
